"""Test headless de l'accueil : pages (glisser, onglets), paramètres, arbre, retour.   python tools/home_test.py"""
import functools, http.server, re, threading, sys, os
from playwright.sync_api import sync_playwright
R=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
class Q(http.server.SimpleHTTPRequestHandler):
    def log_message(self,*a): pass
srv=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Q,directory=R))
threading.Thread(target=srv.serve_forever,daemon=True).start()
errs=[]
def ck(c,m): print(('ok     ' if c else 'ECHEC  ')+m)
with sync_playwright() as pw:
    b=pw.chromium.launch(channel='chrome'); p=b.new_page(viewport={'width':420,'height':760})
    p.on('pageerror',lambda e:errs.append(str(e)))
    p.route('**/phaser.min.js',lambda r:r.fulfill(path=R+'/vendor/phaser.min.js'))
    p.route('**/fonts.googleapis.com/**',lambda r:r.fulfill(status=200,content_type='text/css',body=''))
    p.goto('http://127.0.0.1:%d/index.html'%srv.server_address[1])
    p.wait_for_function('window.__ssxScene && window.__ssxScene.scene.isActive("home")',timeout=60000); p.wait_for_timeout(800)
    vis=lambda s: p.evaluate("!document.querySelector('%s').classList.contains('hidden')"%s)
    ck(vis('#home') and not vis('#start'),'accueil visible, ancien menu masqué')
    ck(p.evaluate("document.getElementById('tabMap').classList.contains('on')"),'onglet CARTE actif au départ')
    # 1re partie (progression vide) : DECOLLER lance le tuto, qui ramène ensuite à l'accueil
    p.evaluate("document.getElementById('btnLaunch').click()"); p.wait_for_timeout(2500)
    ck(p.evaluate("window.__ssxScene.tuto===true && window.__ssxScene.running"),'1re partie : DECOLLER lance le tuto')
    p.evaluate("window.__ssxScene.tutoFinish()"); p.wait_for_timeout(1800)
    ck(p.evaluate("window.__ssxScene.scene.isActive('home') && !document.getElementById('home').classList.contains('hidden')"),'fin du tuto : retour à l\'accueil')
    p.mouse.click(380,30); p.wait_for_timeout(500)       # engrenage (vrai clic)
    ck(vis('#settingsMenu'),'engrenage ouvre les paramètres')
    p.evaluate("document.getElementById('btnSettingsBack').click()"); p.wait_for_timeout(500)
    ck(vis('#home') and not vis('#settingsMenu') and not vis('#start'),'retour des paramètres -> accueil')
    def swipe(x0,x1,y=420):
        p.mouse.move(x0,y); p.mouse.down(); p.mouse.move((x0+x1)//2,y); p.mouse.move(x1,y); p.mouse.up(); p.wait_for_timeout(700)
    page=lambda: p.evaluate("window.__ssxScene.scene.get('home').page")
    # sur la carte du monde (planète + niveaux en orbite) : glisser passe d'un niveau à l'autre, pas d'une page à l'autre
    homeSel=lambda: p.evaluate("window.__ssxScene.scene.get('home').homeSel")
    sel0=homeSel()
    swipe(300,80); ck(page()==0 and homeSel()!=sel0,'glisser sur la planète -> niveau suivant')
    swipe(80,320); ck(page()==0 and homeSel()==sel0,'glisser dans l\'autre sens -> niveau précédent')
    p.evaluate("document.getElementById('tabTree').click()"); p.wait_for_timeout(700)
    swipe(6,320); ck(page()==0,'glisser vers la droite depuis le bord (arbre) -> CARTE')
    # R&D : page de droite, une fiche par technologie, achat du prototype, rangs, spécialisation verrouillée
    p.evaluate("localStorage.setItem('ssx_meta_v3', JSON.stringify({v:3,composants:500,rd:{laser_continu:{plan:true}}}))")
    p.evaluate("(()=>{ const h=window.__ssxScene.scene.get('home'); h.scene.sleep(); h.scene.wake(); })()"); p.wait_for_timeout(600)
    p.evaluate("document.getElementById('tabTree').click()"); p.wait_for_timeout(900)
    ck(page()==1 and p.evaluate("document.querySelectorAll('#treeTabs > *').length")==3,"R&D : une page à droite, trois onglets de secteur")
    ck(p.evaluate("document.querySelectorAll('#treeScroll .rdcard').length")==5,"R&D : le secteur 1 affiche ses 5 technologies")
    ck(p.evaluate("document.getElementById('tabTree').classList.contains('buy')"),'point doré : un achat est possible')
    ck(p.evaluate("!!(document.getElementById('btnAscend') || document.getElementById('alertRowSkills') || document.querySelector('#treeRings'))")==False,"plus d'ascension ni d'anneaux d'alerte")
    bt=p.locator('.rdcard[data-tech=laser_continu] .rd-buy')
    ck(bt.is_enabled() and '30' in bt.inner_text(),'LASER CONTINU : prototype à 30, bouton actif')
    nop=p.locator('.rdcard[data-tech=laser_auto] .rd-buy')
    ck(nop.is_disabled() and 'PLAN A RECUPERER' in nop.inner_text(),'LASER AUTO-CIBLEUR sans plan : bouton inactif, ordre à gagner indiqué')
    bt.click(); p.wait_for_timeout(700)
    ck(p.evaluate("getMeta().rd.laser_continu.proto")==True and p.evaluate("getMeta().composants")==470,'prototype acheté : 30 composants débités')
    ck(p.evaluate("document.getElementById('homeFrag').textContent").strip()=='470','achat R&D : compteur de composants mis à jour')
    bt=p.locator('.rdcard[data-tech=laser_continu] .rd-buy')
    ck(bt.is_enabled() and 'RANG' in bt.inner_text(),'après le prototype : le rang 1 est proposé')
    bt.click(); p.wait_for_timeout(500)
    ck(p.evaluate("getMeta().rd.laser_continu.rang")==1 and p.evaluate("getMeta().composants")==445,'rang 1 acheté : 25 composants débités')
    p.evaluate("(()=>{ localStorage.setItem('ssx_meta_v3', JSON.stringify({v:3,composants:5000,rd:{laser_continu:{plan:true,proto:true,rang:9}}})); window.__ssxScene.renderRd(); return 0; })()"); p.wait_for_timeout(300)
    bt=p.locator('.rdcard[data-tech=laser_continu] .rd-buy')
    ck(bt.is_disabled() and 'PIECES DE SECTEUR REQUISES' in bt.inner_text(),'spécialisation sans pièces de secteur : verrouillée')
    p.evaluate("(()=>{ localStorage.setItem('ssx_meta_v3', JSON.stringify({v:3,composants:5000,rd:{bouclier_reactif:{plan:true,proto:true,rang:6}}})); window.__ssxScene.renderRd(); return 0; })()"); p.wait_for_timeout(300)
    bt=p.locator('.rdcard[data-tech=bouclier_reactif] .rd-buy')
    ck(bt.is_disabled() and 'CONCEPTION' in bt.inner_text(),'spécialisation à concevoir : indiquée en conception')
    p.locator('#treeTabs > *').nth(1).click(); p.wait_for_timeout(400)
    ck(p.evaluate("document.querySelectorAll('#treeScroll .rdcard').length")==0 and 'ACCES NON AUTORISE' in p.locator('#treeScroll').inner_text(),'secteur 2 non atteint : ACCES NON AUTORISE')
    # Garage : six postes d'atelier achetables en composants ; l'aimant et le canon s'affichent selon le Mk acheté.
    p.evaluate("document.getElementById('tabHangar').click()"); p.wait_for_timeout(700)
    assert p.locator('#atelierNext').is_visible()
    assert p.locator('#atelierVersion').count()==0
    assert not p.evaluate("window.__ssxScene.scene.get('home').van.visible")
    meta=lambda m: (p.evaluate("(()=>{ localStorage.setItem('ssx_meta_v3', JSON.stringify(%s)); AtelierGarage.refresh(); return 0; })()"%m), p.wait_for_timeout(250))
    meta("{v:3,composants:500}")
    ck(p.locator('#anPosts .an-post-row').count()==6,'garage : six postes d\'atelier')
    ck(p.locator('#anMagnet').is_hidden() and p.locator('#anCannon').is_hidden(),'garage : ni aimant ni canon au Mk 0')
    p.locator('.an-post-row[data-post=coque] .apr-buy').click(); p.wait_for_timeout(900)
    ck(p.evaluate("getMeta().atelier.coque")==1 and p.evaluate("getMeta().composants")==460,'achat coque Mk I : 40 composants débités')
    ck(p.evaluate("document.getElementById('homeFrag').textContent").strip()=='460','achat atelier : compteur de composants mis à jour')
    ck(p.evaluate("localStorage.getItem('ssx_atelier_preview_module')") is None,'plus de sélecteur d\'aperçu des modules')
    p.locator('.an-post-row[data-post=aimant] .apr-buy').click(); p.wait_for_timeout(300)
    ck(p.locator('#anMagnet').is_visible() and 'aimant' in p.locator('#anMagnet').get_attribute('src'),'aimant Mk I : l\'aimant apparaît sur la camionnette')
    p.locator('.an-post-row[data-post=canon] .apr-buy').click(); p.wait_for_timeout(300)
    ck(p.locator('#anCannon').is_visible() and 'canon' in p.locator('#anCannon').get_attribute('src'),'canon Mk I : le canon apparaît sur la camionnette')
    meta("{v:3,composants:5000,atelier:{coque:2}}")
    bt=p.locator('.an-post-row[data-post=coque] .apr-buy')
    ck(bt.is_disabled() and 'PIECES DE SECTEUR REQUISES' in bt.inner_text(),'Mk III sans pièces de secteur : verrouillé')
    meta("{v:3,composants:5000,atelier:{coque:2},pieces:{s1:2}}")
    p.locator('.an-post-row[data-post=coque] .apr-buy').click(); p.wait_for_timeout(300)
    ck(p.evaluate("getMeta().atelier.coque")==3 and p.evaluate("getMeta().pieces.s1")==0,'Mk III avec 2 pièces du secteur 1 : acheté, pièces débitées')
    meta("{v:3,composants:5000,atelier:{coque:5}}")
    bt=p.locator('.an-post-row[data-post=coque] .apr-buy')
    ck(bt.is_disabled() and bt.inner_text().strip()=='MAX','poste au Mk V : MAX')
    meta("{v:3,composants:30}")
    ck(p.locator('.an-post-row[data-post=coque] .apr-buy').is_disabled(),'composants insuffisants : achat impossible')
    ck(p.evaluate("getMeta().atelier.coque")==0 and p.locator('#anMagnet').is_hidden() and p.locator('#anCannon').is_hidden(),'progression remise à zéro : camionnette de base')
    for category in ['paint','body','modules']:
        p.locator('[data-section='+category+']').click()
    ck(True,'garage unique : catégories peinture, carrosserie et postes')
    p.evaluate("document.getElementById('tabTree').click()"); p.wait_for_timeout(700)
    # arbre : glisser sur les onglets de branche = les faire défiler (pas de changement de page) ; ailleurs = changer de page
    ty=p.evaluate("(()=>{const r=document.getElementById('treeTabs').getBoundingClientRect(); return Math.round(r.top+r.height/2)})()")
    swipe(300,120,y=ty); ck(page()==1,"glisser sur les onglets de l'arbre ne change pas de page")
    swipe(80,330,y=500); ck(page()==0,"glisser vers la droite sur les cartes -> retour à la carte")
    # carte stellaire
    mode=lambda: p.evaluate("window.__ssxScene.scene.get('home').mapMode")
    p.evaluate("document.getElementById('tabMap').click()"); p.wait_for_timeout(500)
    p.evaluate("document.getElementById('tabMap').click()"); p.wait_for_timeout(1500)
    ck(mode()=='galaxy' and p.evaluate("document.getElementById('pageMap').dataset.mode")=='galaxy','onglet CARTE -> carte stellaire')
    gy=lambda: p.evaluate("window.__ssxScene.scene.get('home').galY")
    y0=gy(); p.mouse.move(200,300); p.mouse.down(); p.mouse.move(200,360); p.mouse.move(200,420); p.mouse.up(); p.wait_for_timeout(900)
    ck(gy()!=y0,'défilement vertical au doigt')
    pos=p.evaluate("(()=>{const h=window.__ssxScene.scene.get('home'); return h.galWorlds.map(g=>[g.pos.x,g.pos.y+h.galY]) })()")
    p.mouse.click(pos[1][0],pos[1][1]); p.wait_for_timeout(500)
    ck(mode()=='galaxy' and p.evaluate("document.getElementById('homeToast').classList.contains('show')"),'monde verrouillé : message, on reste sur la carte')
    p.mouse.click(pos[0][0],pos[0][1]); p.wait_for_timeout(2200)
    ck(mode()=='world' and p.evaluate("document.getElementById('mwName').textContent")=='ORBITE TERRESTRE','toucher un monde ouvert -> vue du monde')
    sel=p.evaluate("window.__ssxScene.scene.get('home').homeSel")
    prow=p.evaluate("(()=>{ const r=[...document.querySelectorAll('.om-row')].find(x=>x.textContent.indexOf('PRIME')>=0); return r ? r.textContent : ''; })()")
    pv=p.evaluate("composantsPrime(levelById('%s').reward, false)" % sel)
    ck(re.search(r'\+%d(?!\d)' % pv, prow) is not None,'fiche d\'ordre : prime AGP affichée (+%s dans « %s »)' % (pv, prow))
    ck(p.evaluate("document.querySelectorAll('#mapOrbit .node').length")==6,'6 niveaux en orbite (tuto + 5)')
    # déblocage animé : monde 1 terminé -> le monde 2 se débloque au retour sur l'accueil
    p.evaluate("localStorage.setItem('ssx_worlds_v1', JSON.stringify({v:1,levels:{'w1-l1':{clears:1,best:5},'w1-l2':{clears:1,best:5},'w1-l3':{clears:1,best:5},'w1-l4':{clears:1,best:5},'w1-l5':{clears:1,best:5}},seen:{},last:'w1-l5'}))")
    p.evaluate("(()=>{ const h=window.__ssxScene.scene.get('home'); h.scene.sleep(); h.scene.wake(); })()"); p.wait_for_timeout(500)
    p.wait_for_function("window.__ssxScene.scene.get('home').mapMode==='galaxy'", timeout=30000); p.wait_for_timeout(500)
    ck(p.evaluate("wasWorldSeen('w:w2')") and p.evaluate("document.getElementById('homeToast').textContent").startswith('NOUVEAU SECTEUR'),'nouveau monde : animation de déblocage jouée une fois')
    pos=p.evaluate("(()=>{const h=window.__ssxScene.scene.get('home'); return h.galWorlds.map(g=>[g.pos.x,g.pos.y+h.galY]) })()")
    p.mouse.click(pos[1][0],pos[1][1]); p.wait_for_timeout(2200)
    ck(mode()=='world' and p.evaluate("document.getElementById('mwName').textContent")=='LA CASSE LUNAIRE','le monde 2 est maintenant ouvert')
    p.evaluate("(()=>{ const h=window.__ssxScene.scene.get('home'); h.scene.sleep(); h.scene.wake(); })()"); p.wait_for_timeout(800)
    ck(mode()=='world' and not p.evaluate("wasWorldSeen('w:w2')")==False,'à nouveau sur l\'accueil : pas de rejeu de l\'animation')
    # Baies d'équipement : emplacements ouverts selon les boss, une seule ARME et une seule RAMPE, ligne de chargement de la fiche d'ordre
    p.evaluate("document.getElementById('tabHangar').click()"); p.wait_for_timeout(800)
    RDP="{laser_continu:{plan:true,proto:true},laser_auto:{plan:true,proto:true},missiles_guidage:{plan:true,proto:true}}"
    bays=lambda levels: (p.evaluate("(()=>{ localStorage.setItem('ssx_worlds_v1', JSON.stringify({v:1,levels:%s,seen:{},comp:{}})); localStorage.setItem('ssx_meta_v3', JSON.stringify({v:3,composants:0,rd:%s})); AtelierGarage.refresh(); document.getElementById('atelierNext').scrollTop=0; return 0; })()"%(levels,RDP)), p.locator('[data-section=baies]').click(), p.wait_for_timeout(300))
    tech=lambda t: p.locator('.bay-tech[data-tech=%s] button'%t)
    bays("{}")
    ck(p.locator('.bay:not(.lock)').count()==1 and p.locator('.bay-lock').count()==3 and 'AUTORISATION REQUISE' in p.locator('.bay-lock').first.inner_text(),'baies : 1 ouverte, 3 verrouillées (AUTORISATION REQUISE)')
    tech('laser_continu').click(); p.wait_for_timeout(300)
    ck(p.evaluate("JSON.stringify(getMeta().chargement)")=='["laser_continu"]','équiper le LASER CONTINU')
    tech('laser_auto').click(); p.wait_for_timeout(300)
    ck(p.evaluate("JSON.stringify(getMeta().chargement)")=='["laser_continu"]' and 'baie' in p.locator('#anDescription').inner_text(),'baie pleine : 2e technologie refusée avec le message de N.O.R.M.A.')
    bays("{'w1-l5':{clears:1,best:1}}")
    ck(p.locator('.bay:not(.lock)').count()==2,'boss du secteur 1 vaincu : 2e baie ouverte')
    tech('laser_continu').click(); p.wait_for_timeout(300); tech('laser_continu').click(); p.wait_for_timeout(300)
    ck(p.evaluate("JSON.stringify(getMeta().chargement)")=='[]','équiper puis retirer : le chargement redevient vide')
    tech('laser_auto').click(); p.wait_for_timeout(300)
    ck(p.evaluate("JSON.stringify(getMeta().chargement)")=='["laser_auto"]','une fois la baie libre : l\'autre ARME est acceptée')
    p.evaluate("(()=>{ const m=getMeta(); m.chargement=['laser_continu']; setMeta(m); AtelierGarage.refresh(); return 0; })()"); p.wait_for_timeout(200)
    tech('laser_auto').click(); p.wait_for_timeout(300)
    ck(p.evaluate("JSON.stringify(getMeta().chargement)")=='["laser_continu"]' and 'ARME' in p.locator('#anDescription').inner_text(),'une seule ARME par chargement')
    tech('missiles_guidage').click(); p.wait_for_timeout(300)
    ck(p.evaluate("JSON.stringify(getMeta().chargement)")=='["laser_continu","missiles_guidage"]','ARME + RAMPE acceptées avec 2 baies')
    p.evaluate("(()=>{ const h=window.__ssxScene.scene.get('home'); h.homeWorld=0; h.selectHomeLevel('w1-l1'); return 0; })()"); p.wait_for_timeout(400)
    ck('CHARGEMENT' in p.locator('#levelCard').inner_text() and 'LASER CONTINU' in p.locator('#levelCard').inner_text(),'fiche d\'ordre : ligne CHARGEMENT avec les noms')
    p.evaluate("document.getElementById('btnLoadout').click()"); p.wait_for_timeout(900)
    ck(page()==-1 and p.locator('[data-section=baies]').get_attribute('aria-pressed')=='true','MODIFIER : ouvre le garage sur les baies')
    p.evaluate("(()=>{ const h=window.__ssxScene.scene.get('home'); h.homeWorld=0; h.selectHomeLevel('w1-tuto'); return 0; })()"); p.wait_for_timeout(400)
    ck('CHARGEMENT' not in p.locator('#levelCard').inner_text(),'fiche du tutoriel : pas de ligne CHARGEMENT')
    # avis de migration : il n'est consommé qu'à la première interaction avec le garage, pas au démarrage
    p.evaluate("localStorage.setItem('ssx_meta_v3', JSON.stringify({v:3,composants:50,notice:'restructuration'}))")
    p.goto('http://127.0.0.1:%d/index.html'%srv.server_address[1])
    p.wait_for_function('window.__ssxScene && window.__ssxScene.scene.isActive("home")',timeout=60000); p.wait_for_timeout(1200)
    ck(p.evaluate("getMeta().notice")=='restructuration','avis de migration : toujours en attente tant que le garage n\'a pas été utilisé')
    p.evaluate("document.getElementById('tabHangar').click()"); p.wait_for_timeout(700)
    ck('restructur' in p.locator('#anDescription').inner_text(),'avis de migration : affiché dans le garage')
    p.locator('[data-section=paint]').click(); p.wait_for_timeout(200)
    ck(p.evaluate("getMeta().notice")==None,'avis de migration : consommé après une interaction')
    b.close()
print('erreurs JS:',errs)
sys.exit(1 if errs else 0)
